function runTheTicker(){ var myTimeout; // Go for the next story data block if(theCurrentLength == 0) { theCurrentStory++; theCurrentStory = theCurrentStory % theItemCount; theStorySummary = theSummaries[theCurrentStory].replace(/&quot;/g,'"'); theTargetLink = theSiteLinks[theCurrentStory]; theAnchorObject.href = theTargetLink; thePrefix = "<span class=\"tickls\">" + theLeadString + "</span>"; } // Stuff the current ticker text into the anchor theAnchorObject.innerHTML = thePrefix + theStorySummary.substring(0,theCurrentLength) + whatWidget(); // Modify the length for the substring and define the timer if(theCurrentLength != theStorySummary.length) { theCurrentLength++; myTimeout = theCharacterTimeout; } else { theCurrentLength = 0; myTimeout = theStoryTimeout; } // Call up the next cycle of the ticker setTimeout("runTheTicker()", myTimeout);
} // Widget generator
